  "content": "1|export type ProfileFieldDataKind = 'string' | 'base_info_code' | 'image';
2|
3|export type ProfileFieldDefinition = {
4|  profileField: string;
5|  label: string;
6|  dataKind: ProfileFieldDataKind;
7|  viewOrder: number;
8|  /** Null means the field is virtual and not backed by a single DB column. */
9|  dbColumn: string | null;
10|};
11|
12|/** Columns on base_user_profiles that are never exposed in Profile Fields settings. */
13|export const PROFILE_TABLE_SYSTEM_COLUMNS = new Set([
14|  'user_id',
15|  'created_at',
16|  'created_by',
17|  'updated_at',
18|  'updated_by',
19|]);
20|
21|/** Image storage columns are grouped under the virtual profile_image field. */
22|export const PROFILE_IMAGE_STORAGE_COLUMNS = new Set([
23|  'profile_image_body',
24|  'profile_image_body_xs',
25|  'profile_image_mime',
26|  'profile_image_size',
27|]);
28|
29|export const PROFILE_FIELD_DEFINITIONS: ProfileFieldDefinition[] = [
30|  { profileField: 'profile_image', label: 'Profile Image', dataKind: 'image', viewOrder: 0, dbColumn: null },
31|  { profileField: 'firstname', label: 'First Name', dataKind: 'string', viewOrder: 10, dbColumn: 'firstname' },
32|  { profileField: 'lastname', label: 'Last Name', dataKind: 'string', viewOrder: 20, dbColumn: 'lastname' },
33|  { profileField: 'fathername', label: 'Father Name', dataKind: 'string', viewOrder: 30, dbColumn: 'fathername' },
34|  { profileField: 'grandfathername', label: 'Grandfather Name', dataKind: 'string', viewOrder: 40, dbColumn: 'grandfathername' },
35|  { profileField: 'phone', label: 'Phone', dataKind: 'string', viewOrder: 50, dbColumn: 'phone' },
36|  { profileField: 'nickname', label: 'Nickname', dataKind: 'string', viewOrder: 60, dbColumn: 'nickname' },
37|  { profileField: 'national_code', label: 'National Code', dataKind: 'string', viewOrder: 70, dbColumn: 'national_code' },
38|  { profileField: 'birth_year', label: 'Birth Year', dataKind: 'string', viewOrder: 80, dbColumn: 'birth_year' },
39|  { profileField: 'birth_month', label: 'Birth Month', dataKind: 'string', viewOrder: 90, dbColumn: 'birth_month' },
40|  { profileField: 'birth_day', label: 'Birth Day', dataKind: 'string', viewOrder: 100, dbColumn: 'birth_day' },
41|  { profileField: 'gender_code', label: 'Gender Code', dataKind: 'base_info_code', viewOrder: 110, dbColumn: 'gender_code' },
42|  { profileField: 'person_type_code', label: 'Person Type Code', dataKind: 'base_info_code', viewOrder: 120, dbColumn: 'person_type_code' },
43|];
44|
45|const PROFILE_FIELD_DEFINITION_BY_FIELD = new Map(
46|  PROFILE_FIELD_DEFINITIONS.map((definition) => [definition.profileField, definition]),
47|);
48|
49|const PROFILE_FIELD_DEFINITION_BY_DB_COLUMN = new Map(
50|  PROFILE_FIELD_DEFINITIONS
51|    .filter((definition): definition is ProfileFieldDefinition & { dbColumn: string } => Boolean(definition.dbColumn))
52|    .map((definition) => [definition.dbColumn, definition]),
53|);
54|
55|export const toDefaultProfileFieldLabel = (profileField: string): string =>
56|  profileField
57|    .split('_')
58|    .filter(Boolean)
59|    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
60|    .join(' ');
61|
62|export const inferProfileFieldDataKind = (profileField: string): ProfileFieldDataKind => {
63|  if (profileField === 'profile_image') return 'image';
64|  if (profileField === 'gender_code' || profileField === 'person_type_code') return 'base_info_code';
65|  return 'string';
66|};
67|
68|export const getProfileFieldDefinition = (profileField: string): ProfileFieldDefinition | null =>
69|  PROFILE_FIELD_DEFINITION_BY_FIELD.get(profileField) ?? null;
70|
71|export const getProfileFieldLabel = (profileField: string): string =>
72|  getProfileFieldDefinition(profileField)?.label ?? toDefaultProfileFieldLabel(profileField);
73|
74|export const resolveConfigurableProfileFields = (dbColumns: string[]): ProfileFieldDefinition[] => {
75|  const configurableDbColumns = dbColumns.filter((column) =>
76|    !PROFILE_TABLE_SYSTEM_COLUMNS.has(column)
77|    && !PROFILE_IMAGE_STORAGE_COLUMNS.has(column),
78|  );
79|
80|  const resolved: ProfileFieldDefinition[] = [];
81|  const seenFields = new Set<string>();
82|
83|  for (const definition of PROFILE_FIELD_DEFINITIONS) {
84|    if (definition.dbColumn === null) {
85|      resolved.push(definition);
86|      seenFields.add(definition.profileField);
87|      continue;
88|    }
89|
90|    if (configurableDbColumns.includes(definition.dbColumn)) {
91|      resolved.push(definition);
92|      seenFields.add(definition.profileField);
93|    }
94|  }
95|
96|  for (const column of configurableDbColumns) {
97|    const mappedDefinition = PROFILE_FIELD_DEFINITION_BY_DB_COLUMN.get(column);
98|    if (mappedDefinition) continue;
99|
100|    if (seenFields.has(column)) continue;
101|
102|    resolved.push({
103|      profileField: column,
104|      label: toDefaultProfileFieldLabel(column),
105|      dataKind: inferProfileFieldDataKind(column),
106|      viewOrder: 1000 + resolved.length,
107|      dbColumn: column,
108|    });
109|    seenFields.add(column);
110|  }
111|
112|  return resolved.sort((left, right) => {
113|    const orderDiff = left.viewOrder - right.viewOrder;
114|    if (orderDiff !== 0) return orderDiff;
115|    return left.profileField.localeCompare(right.profileField);
116|  });
117|};
118|
119|export const PROFILE_FIELD_OPTIONS = PROFILE_FIELD_DEFINITIONS.map((definition) => ({
120|  value: definition.profileField,
121|  label: definition.label,
122|}));
